import "@testing-library/jest-dom/vitest";
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { App } from "./App";

describe("account management", () => {
  it("renders the customer name", () => {
    render(<App />);
    expect(screen.getByRole("heading", { name: "株式会社ノーススター" })).toBeInTheDocument();
  });
});

import { companyFixture } from "./fixtures";

export function App() {
  return (
    <main>
      <h1>{companyFixture.name}</h1>
      <p>brief.mdの要件に沿って、この画面を実装してください。</p>
    </main>
  );
}

export type UserRole = "manager" | "viewer";

export const companyFixture = {
  id: "company_northstar",
  name: "株式会社ノーススター",
  status: "契約中",
  plan: "Business",
  contractStart: "2026-04-01",
  contractEnd: "2027-03-31",
  seats: 50,
  usedSeats: 42,
